import{_ as t,o as n,c as a,a0 as o}from"./chunks/framework.ZC3WYqLu.js";const i="/cass-editor/docs/assets/configurations.CVnkkbfS.png",r="/cass-editor/docs/assets/browser-default.CX2PBzmV.png",s="/cass-editor/docs/assets/view-manage-delete.S820qIjE.png",c="/cass-editor/docs/assets/create-new-configuration.Bl8WSys5.png",g="/cass-editor/docs/assets/general-details.C5xVwL00.png",l="/cass-editor/docs/assets/save-configuration.BYxWk_og.png",w=JSON.parse('{"title":"Configurations","description":"","frontmatter":{},"headers":[],"relativePath":"authoring/configuration/index.md","filePath":"authoring/configuration/README.md"}'),f={name:"authoring/configuration/index.md"};function u(d,e,h,p,m,b){return n(),a("div",null,[...e[0]||(e[0]=[o('<h1 id="configurations" tabindex="-1">Configurations <a class="header-anchor" href="#configurations" aria-label="Permalink to &quot;Configurations&quot;">​</a></h1><div class="tip custom-block"><p class="custom-block-title">Note</p><p>This section is not applicable to Credential Engine instances of CAT.</p></div><p>Configurations control the way frameworks and competencies appear in the editor, as well as what properties, relationships, and in some cases value types of properties and relationships that can be added to frameworks and competencies.</p><p>Configurations are set at the framework object. If a framework does not have a configuration assigned, then the following priority is made to determine the correct configuration to apply to the display of the framework:</p><ol><li>Browser default configuration</li><li>Instance default configuration</li><li>CaSS nomenclature fallback</li></ol><div class="tip custom-block"><p class="custom-block-title">Note</p><p>Only a single configuration can be set to the instance default at any given time. In order to change the instance default, the owner of the current instance default must toggle the default switch off. At that point, another configuration can be set as the instance default.</p></div><h2 id="accessing-the-cat-configuration-manager" tabindex="-1">Accessing the CAT Configuration Manager <a class="header-anchor" href="#accessing-the-cat-configuration-manager" aria-label="Permalink to &quot;Accessing the CAT Configuration Manager&quot;">​</a></h2><p>The CAT configuration manager can be accessed at any time by selecting the <em><strong>configurations</strong></em> icon on the lower left corner of the navigation menu.</p><p><img src="'+i+'" alt="Configurations Navigation Menu"></p><p>Upon entering the configuration manager, a list of all existing configurations in the current CAT instance are displayed. Public configurations or configurations owned by the current logged in user can be managed or deleted by selecting one of the actions icons to the right of the configuration item. Unowned configurations can be viewed by selecting the appropriate action icon.</p><p><img src="'+r+'" alt="Configuration Action Browser Default"></p><p>It is also possible for users to set their browser default configuration from this screen</p><p><img src="'+s+'" alt="Browser Default"></p><h2 id="creating-a-new-configuration" tabindex="-1">Creating a New Configuration <a class="header-anchor" href="#creating-a-new-configuration" aria-label="Permalink to &quot;Creating a New Configuration&quot;">​</a></h2><p>Configurations can be created by clicking the <em><strong>create new configuration</strong></em> button at the bottom right corner of the configuration management list screen. By default, all required fields are pre-populated with default CaSS terminology and settings.</p><p><img src="'+c+'" alt="Create new Configuration"></p><h2 id="managing-a-configuration" tabindex="-1">Managing a Configuration <a class="header-anchor" href="#managing-a-configuration" aria-label="Permalink to &quot;Managing a Configuration&quot;">​</a></h2><p>After creating a new configuration or selecting the <em><strong>manage</strong></em> action on an existing configuration, the configuration details screen is displayed. This screen is divided into the following sections:</p><h3 id="configuration-general-details" tabindex="-1">Configuration General Details <a class="header-anchor" href="#configuration-general-details" aria-label="Permalink to &quot;Configuration General Details&quot;">​</a></h3><p><img src="'+g+'" alt="General Details"></p><p>The general details configuration settings provide fields for editing the <em><strong>name</strong></em> and <em><strong>description</strong></em> of the configuration. From this section you can also toggle the <em><strong>instance default</strong></em> switch and set your browser default.</p><div class="tip custom-block"><p class="custom-block-title">Note</p><p>Only a single configuration can be set to the instance default at any given time. In order to change the instance default, the owner of the current instance default must toggle the default switch off. At that point, another configuration can be set as the instance default.</p></div><h3 id="saving-the-configuration" tabindex="-1">Saving the Configuration <a class="header-anchor" href="#saving-the-configuration" aria-label="Permalink to &quot;Saving the Configuration&quot;">​</a></h3><p>Configurations can be saved by clicking on the <em><strong>save configuration</strong></em> button on the left side of the <em><strong>configuration details</strong></em> screen.</p><p><img src="'+l+'" alt="Save Configuration"></p>',25)])])}const _=t(f,[["render",u]]);export{w as __pageData,_ as default};
